from concurrent.futures import ThreadPoolExecutor
from time import perf_counter, sleep

def waiting(_: int) -> int:
    sleep(0.05)          # releases the GIL while the OS waits
    return 1

def python_cpu(_: int) -> int:
    return sum(i * i for i in range(600_000))

def measure(fn, workers: int, tasks: int = 32) -> float:
    start = perf_counter()
    with ThreadPoolExecutor(max_workers=workers) as pool:
        list(pool.map(fn, range(tasks)))
    return perf_counter() - start

for fn in (waiting, python_cpu):
    for workers in (1, 4, 16):
        print(fn.__name__, workers, measure(fn, workers))
